import{_ as e,c as t,o as r,ag as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy.md","filePath":"zh-CN/guide/privacy.md","lastUpdated":1791311600000}'),l={name:"zh-CN/guide/privacy.md"};function o(n,a,d,s,h,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>nPlyr 是一款面向 macOS 与 iOS 的原生视频播放器。你的隐私是我们的首要任务。</p><h2 id="本地优先设计" tabindex="-1">本地优先设计 <a class="header-anchor" href="#本地优先设计" aria-label="Permalink to &quot;本地优先设计&quot;">​</a></h2><ul><li>你的观看历史、书签与下载内容<strong>完全存储在你自己的设备上</strong>。</li><li>应用<strong>不需要账号，也不需要注册</strong>。</li><li><strong>没有遥测</strong>——nPlyr 不会将使用数据回传。</li><li>一旦媒体已在你的设备上，核心播放与下载功能可完全离线工作。</li></ul><h2 id="网络使用由用户主导" tabindex="-1">网络使用由用户主导 <a class="header-anchor" href="#网络使用由用户主导" aria-label="Permalink to &quot;网络使用由用户主导&quot;">​</a></h2><p>nPlyr 只在<em>你</em>要求时才使用网络：</p><ul><li>流式播放或下载你打开或抓取的视频。</li><li>使用内置嗅探器浏览。</li><li>运行你导入的小程序 / 规则源。</li></ul><p>我们不运营接收你的媒体、历史或小程序变量的服务器。</p><h2 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h2><p>内置浏览器是一个标准的 <code>WKWebView</code>。它不会注入自身的追踪器。Cookie 与本地存储都留在应用的容器内，与其他任何浏览器一样。</p><h2 id="小程序数据" tabindex="-1">小程序数据 <a class="header-anchor" href="#小程序数据" aria-label="Permalink to &quot;小程序数据&quot;">​</a></h2><p>小程序是社区提供的规则，运行在沙盒化的 JavaScript 引擎中。规则存储的任何变量（<code>setItem</code> / <code>getItem</code>）都保存在你设备上的应用本地存储中。nPlyr 不会读取或传输它们。</p><h2 id="调试日志" tabindex="-1">调试日志 <a class="header-anchor" href="#调试日志" aria-label="Permalink to &quot;调试日志&quot;">​</a></h2><p>如果你启用了调试日志，日志会被写入本地，并且只有在<em>你</em>选择导出它们以报告问题时才会被分享。</p><h2 id="你的选择" tabindex="-1">你的选择 <a class="header-anchor" href="#你的选择" aria-label="Permalink to &quot;你的选择&quot;">​</a></h2><ul><li>随时删除单个历史 / 书签 / 下载条目。</li><li>从<strong>设置 → 高级 → 重置</strong>重置所有本地数据。</li><li>从<strong>小程序</strong>管理器中移除一个小程序及其存储的变量。</li></ul><p>nPlyr 的设计默认就是私密的——没有什么需要&quot;退出&quot;。</p>',17)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
